39	export function fixJitter(
40	    fixedAxis: Axis2D | SingleAxis,
41	    fixedCoord: number,
42	    floatCoord: number,
43	    radius: number
44	): number {
45	    if (fixedAxis instanceof Axis2D) {
46	        const scaleType = fixedAxis.scale.type;
47	        if (scaleType !== 'category' && scaleType !== 'ordinal') {
48	            return floatCoord;
49	        }
50	    }
51	    const axisModel = fixedAxis.model as AxisBaseModel;
52	    const jitter = axisModel.get('jitter');
53	    const jitterOverlap = axisModel.get('jitterOverlap');
54	    const jitterMargin = axisModel.get('jitterMargin') || 0;
55	    // Get band width to limit jitter range
56	    const bandWidth = fixedAxis.scale.type === 'ordinal'
57	        ? fixedAxis.getBandWidth()
58	        : null;
59	    if (jitter > 0) {
60	        if (jitterOverlap) {
61	            return fixJitterIgnoreOverlaps(floatCoord, jitter, bandWidth, radius);
62	        }
63	        else {
