70	function fixJitterIgnoreOverlaps(
71	    floatCoord: number,
72	    jitter: number,
73	    bandWidth: number | null,
74	    radius: number
75	): number {
76	    // Don't clamp single axis
77	    if (bandWidth === null) {
78	        return floatCoord + (Math.random() - 0.5) * jitter;
79	    }
80	    const maxJitter = bandWidth - radius * 2;
81	    const actualJitter = Math.min(Math.max(0, jitter), maxJitter);
82	    return floatCoord + (Math.random() - 0.5) * actualJitter;
83	}
