145	function placeJitterOnDirection(
146	    items: JitterData,
147	    fixedCoord: number,
148	    floatCoord: number,
149	    radius: number,
150	    jitter: number,
151	    margin: number,
152	    direction: 1 | -1
153	): {
154	    resultCoord: number;
155	    insertBy: JitterData;
156	    direction: 1 | -1;
157	} {
158	    // Check for overlap with previous items.
159	    let y = floatCoord;
160	    const pointer1 = direction > 0 ? 'next' : 'prev';
161	    let insertBy = items;
162	    let item = items[pointer1];
163	
164	    while (item !== items) {
165	        const dx = fixedCoord - item.fixedCoord;
166	        const dy = y - item.floatCoord;
167	        const d2 = dx * dx + dy * dy;
168	        const r = radius + item.r + margin;
169	        if (d2 < r * r) {
170	            // Overlap. Try to move the new item along otherCoord direction.
171	            y = item.floatCoord + Math.sqrt(r * r - dx * dx) * direction;
172	            insertBy = item;
173	
174	            if (Math.abs(y - floatCoord) > jitter / 2) {
175	                // If the new item is moved too far, then give up.
176	                // Fall back to random jitter.
177	                return {resultCoord: Number.MAX_VALUE, insertBy, direction};
178	            }
179	        }
180	
181	        item = item[pointer1];
182	    }
183	
184	    return {resultCoord: y, insertBy, direction};
185	}
